class Main {
	public static var out:Array<String> = [];

	static function t(s:String):Void {
		out.push(s);
	}

	static function plain(c:Bool):Void {
		if (c) {
			out.push('a');
			t('t');
		} else {
			out.push('b');
			t('t');
		}
	}

	static function chain(c:Int):Void {
		if (c == 0) {
			out.push('0');
			t('x');
			t('y');
		} else if (c == 1) {
			out.push('1');
			t('x');
			t('y');
		} else {
			out.push('2');
			t('x');
			t('y');
		}
	}

	static function emptied(c:Bool):Void {
		if (c) {
			out.push('a');
			t('t');
		} else {
			t('t');
		}
	}

	static function early(c:Bool):Int {
		if (c) {
			if (out.length > 100) return 1;
			out.push('a');
			t('t');
		} else {
			out.push('b');
			t('t');
		}
		return 0;
	}

	static function loopBody(c:Bool):Void {
		for (i in 0...2) if (c) {
			out.push('a$i');
			t('t');
		} else {
			out.push('b$i');
			t('t');
		}
	}

	static function captured(c:Bool):Void {
		if (c) {
			final v = 1;
			t('v$v');
		} else {
			final v = 2;
			t('v$v');
		}
	}

	static function exits(c:Bool):Void {
		if (c) {
			out.push('a');
			return;
		} else {
			out.push('b');
			return;
		}
	}

	static function main():Void {
		for (c in [true, false]) {
			plain(c);
			emptied(c);
			early(c);
			loopBody(c);
			captured(c);
			exits(c);
		}
		for (i in 0...3) chain(i);
		Sys.println(out.join(','));
	}
}

